import{_ as t,o,c as r,a0 as a}from"./chunks/framework.D0vMsDwd.js";const u=JSON.parse('{"title":"Using the REPL","description":"","frontmatter":{"title":"Using the REPL","outline":[2,2]},"headers":[],"relativePath":"using-the-repl.md","filePath":"using-the-repl.md"}'),n={name:"using-the-repl.md"};function s(i,e,l,d,c,h){return o(),r("div",null,e[0]||(e[0]=[a('<h1 id="using-the-repl" tabindex="-1">Using the REPL <a class="header-anchor" href="#using-the-repl" aria-label="Permalink to &quot;Using the REPL&quot;">​</a></h1><p>The <a href="./repl.html">nP REPL</a> lets you run JavaScript with the site&#39;s nP browser bundle. The editor starts empty. Type your own code or choose a starter example from the left sidebar, then press <strong>Run</strong>. Results appear in <strong>Output</strong> below the editor. Each run uses a fresh, isolated output frame.</p><p>For circuits that depend on frequency, set <code>nP.global.fList</code> before creating components. Use <code>nP.log(...)</code> to show values in <strong>Output</strong>. Use <code>console.log(...)</code> when you want to inspect values in the browser&#39;s developer console.</p><h2 id="buttons" tabindex="-1">Buttons <a class="header-anchor" href="#buttons" aria-label="Permalink to &quot;Buttons&quot;">​</a></h2><ul><li><strong>Run</strong> checks the current code for lint warnings, then executes it.</li><li><strong>View output</strong> scrolls to the Output area.</li><li><strong>Clear</strong> empties both the editor and Output and clears the current editor buffer. You can select the same example again afterward.</li><li><strong>Reset example</strong> restores the selected starter example to its original code. It is available after you select an example.</li><li><strong>View code</strong> beside the Output heading scrolls back to the editor.</li></ul><h2 id="run-a-starter-example" tabindex="-1">Run a starter example <a class="header-anchor" href="#run-a-starter-example" aria-label="Permalink to &quot;Run a starter example&quot;">​</a></h2><ol><li>Open the <a href="./repl.html">REPL</a> and choose an example in its left sidebar. Its JavaScript loads into the editor.</li><li>Read or edit the code, then press <strong>Run</strong>.</li><li>Inspect <strong>Output</strong>. A chart or table appears there when the example calls <code>nP.lineChart()</code>, <code>nP.smithChart()</code>, or <code>nP.lineTable()</code>.</li></ol><p>You can also begin with an empty editor and type your own circuit. Selecting a different example replaces the editor contents. <strong>Reset example</strong> restores the currently selected example; <strong>Clear</strong> removes the selection and leaves the editor blank.</p><h2 id="copy-and-paste-png-or-csv" tabindex="-1">Copy and paste PNG or CSV <a class="header-anchor" href="#copy-and-paste-png-or-csv" aria-label="Permalink to &quot;Copy and paste PNG or CSV&quot;">​</a></h2><p>Charts and tables provide their own copy buttons inside <strong>Output</strong>:</p><ul><li>On a line chart, Smith chart, or line table, click <strong>Copy PNG</strong> to put an image on the clipboard. Switch to an application that accepts pasted images and press <strong>Ctrl+V</strong> (or use that application&#39;s Paste command).</li><li>On a line table, click <strong>Copy CSV</strong> to put comma-separated table text on the clipboard. Paste it into a spreadsheet or text editor.</li></ul><p>These buttons copy to the clipboard; they do not save a <code>.png</code> or <code>.csv</code> file. Your browser may ask for clipboard permission. Clipboard copying works on the published HTTPS site and on a local <code>localhost</code> preview when the browser supports the relevant clipboard format.</p><h2 id="automatic-lint-warnings" tabindex="-1">Automatic lint warnings <a class="header-anchor" href="#automatic-lint-warnings" aria-label="Permalink to &quot;Automatic lint warnings&quot;">​</a></h2><p>When you press <strong>Run</strong>, the REPL checks the editor before execution. Warnings appear immediately below the Run buttons and above the editor. Click a warning&#39;s line number to move the editor cursor there. Warnings do not prevent the code from running.</p><p>The current checks look for unexpected line continuations, accidental comma expressions, and direct calls to unknown nP API names. For example, <code>nP.r()</code> suggests <code>nP.R()</code>. The linter also reports JavaScript syntax errors. It checks direct calls such as <code>nP.R()</code>; it cannot reliably identify every name reached through variables or computed expressions.</p><h2 id="debug-with-devtools" tabindex="-1">Debug with DevTools <a class="header-anchor" href="#debug-with-devtools" aria-label="Permalink to &quot;Debug with DevTools&quot;">​</a></h2><ol><li>Press <strong>Run</strong> and read the error in <strong>Output</strong>. A stack trace shows where the error was detected; the mistake may be on an earlier line.</li><li>Open your browser&#39;s developer tools and select <strong>Console</strong>. The REPL also logs the error there as an Error object. Your own <code>console.log(...)</code> messages appear there too.</li><li>In the Console error, find the stack entry containing <strong><code>np-debug.js:line:column</code></strong> and click it. DevTools opens the code from that run in <strong>Sources</strong> at the indicated location. If the first entries point to <code>nP.js</code>, look farther down the stack for <code>np-debug.js</code>; that is your editor code.</li><li>Check the indicated line and the code that builds its inputs. Fix the editor text and press <strong>Run</strong> again.</li></ol><p><code>np-debug.js</code> is a name the REPL gives to the code it runs so DevTools can find it. It is not a file you need to create or find in the repository. DevTools may show a small line offset because the browser wraps the editor code before running it.</p><h2 id="editor-storage-and-the-browser-tab" tabindex="-1">Editor storage and the browser tab <a class="header-anchor" href="#editor-storage-and-the-browser-tab" aria-label="Permalink to &quot;Editor storage and the browser tab&quot;">​</a></h2><p>The REPL keeps <strong>one editor buffer</strong> in the browser tab used for the nP site. Edits survive a refresh and navigation between the landing page and REPL in that same tab. Loading another example replaces the buffer; <strong>Clear</strong> removes it. Separate tabs do not share ongoing edits.</p><p>Closing that tab normally removes its buffer. Some browsers can restore a closed tab&#39;s session, including its buffer. If you want to keep code independently of the tab, copy it into a file before closing it.</p>',21)]))}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
